{
  "title": "赛博武侠校园历险",
  "scene": "在未来的长安城中，高楼大厦与古老的建筑交相辉映。夕阳的余晖洒在校园的长廊上，空气中弥漫着科技的冰冷与历史的厚重。玩家身处一个校园的废弃教学楼内，这里隐藏着一个古老的秘密。墙角的缝隙中，露出一角蓝色的机器猫模型，仿佛在邀请你探索。墙壁上的电子屏幕显示着期末考试的成绩公告板，而透过窗户，可以看到远处的长安城在夜幕下依然灯火通明。",
  "goal": "找到隐藏在废弃教学楼中的秘密，收集所有线索以完成期末考试。",
  "choices": [
    {
      "id": "A",
      "text": "拿起墙角的蓝色机器猫模型，观察它的内部。",
      "outcome": "机器猫内部藏着一张写有线索的纸条。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "打开窗户，试图从窗户跳出去探索城中的长安。",
      "outcome": "玩家不慎从窗户摔下，但幸运的是没有受伤，掉了几颗牙齿。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "沿着线索，走到废墟中央的一株古老的樱花树下。",
      "outcome": "樱花树下有一把会说话的剑，它自称是‘青龙剑’，愿意帮助玩家找到下个线索。",
      "result": "success",
      "next": "bad_end"
    }
  ]
}
